.venv/bin/python - <<'PY'
import re, serial, time
p='/dev/cu.usbserial-1130'
h=serial.Serial(p,115200,timeout=0.1,write_timeout=1)
h.dtr=False; h.rts=False
end=time.monotonic()+35
raw=bytearray()
while time.monotonic()<end:
    n=h.in_waiting
    if n: raw.extend(h.read(n))
    time.sleep(0.05)
h.reset_input_buffer()
for _ in range(3):
    h.write(b'status\n'); h.flush(); time.sleep(1.5)
    n=h.in_waiting
    if n: raw.extend(h.read(n))
h.close()
text=raw.decode(errors='replace')
print('STAGE28E_A_HW_SERIAL_BYTES', len(raw))
print(text[-30000:])
status=[line for line in text.splitlines() if line.startswith('status ')]
timing=[line for line in text.splitlines() if line.startswith('timing ')]
tasks=[line for line in text.splitlines() if line.startswith('task ')]
if not status: raise SystemExit('missing status line')
if not timing: raise SystemExit('missing timing line')
s=status[-1]
required=['firmware_sha=3058625be2f35c121afcf82549d5c73068839ecd','outputs=fake-locked','internal_free=','internal_min=','internal_largest=','psram_free=','psram_min=','psram_largest=','boot_id=','reset_reason=']
for token in required:
    if token not in s: raise SystemExit('missing status token '+token)
if not tasks: raise SystemExit('missing task diagnostics')
def num(line,key):
    m=re.search(r'(?:^| )'+re.escape(key)+r'=(\d+)', line)
    return int(m.group(1)) if m else None
critical=[]
for line in tasks:
    if 'severity=critical' in line: critical.append(line)
if critical:
    print('STAGE28E_A_HW_CRITICAL_STACK', *critical, sep='\n')
    raise SystemExit('critical stack margin')
print('STAGE28E_A_HW_STATUS', s)
print('STAGE28E_A_HW_TIMING', timing[-1])
known=[]
for line in tasks:
    hwm=num(line,'hwm_bytes')
    if hwm is not None: known.append((hwm,line))
if known:
